<script>var tm;document.getElementById('ps').oninput=function(){clearTimeout(tm);var q=this.value.trim(),box=document.getElementById('pr');if(q.length<2){box.innerHTML='';return}tm=setTimeout(function(){fetch('/admin/purchase/api/products?q='+encodeURIComponent(q),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(a){box.innerHTML='';a.slice(0,8).forEach(function(p){var b=document.createElement('a');b.className='chip';b.style.margin='3px';b.href='?product='+p.id;b.textContent=p.name;box.appendChild(b)})})},250)};</script>@endsection
